    characters: ["Jesus", "Mary Magdalene", "Peter"],
    vocabulary: [{ word: "Cross", meaning: "A wooden structure the Romans used for executions. Christians see it as a sign of Jesus' love." }, { word: "Tomb", meaning: "A cave-like place where someone is buried." }, { word: "Resurrection", meaning: "Coming back to life after dying." }],
    takeaways: ["Jesus loved us so much he gave his life.", "Jesus rose again — he is alive!", "Easter means God's love and life are stronger than death."],
